import{_ as r,C as e,o as n,c as h,j as o,a as s,G as l,a3 as d}from"./chunks/framework.Bvm_liKL.js";const m=JSON.parse('{"title":"常见问题","description":"ICC-CE 使用中的常见问题解答，涵盖安装、运行、PPT 联动、墨迹、性能等方面","frontmatter":{"title":"常见问题","description":"ICC-CE 使用中的常见问题解答，涵盖安装、运行、PPT 联动、墨迹、性能等方面"},"headers":[],"relativePath":"cn/guide/faq.md","filePath":"cn/guide/faq.md"}'),u={name:"cn/guide/faq.md"};function c(q,a,p,b,C,P){const t=e("ArticleMetadata"),i=e("UnderConstruction");return n(),h("div",null,[a[0]||(a[0]=o("h1",{id:"常见问题",tabindex:"-1"},[s("常见问题 "),o("a",{class:"header-anchor",href:"#常见问题","aria-label":'Permalink to "常见问题"'},"​")],-1)),l(t),l(i),a[1]||(a[1]=d('<h2 id="安装与运行" tabindex="-1">安装与运行 <a class="header-anchor" href="#安装与运行" aria-label="Permalink to &quot;安装与运行&quot;">​</a></h2><h3 id="程序无法启动-提示缺少-net-运行时" tabindex="-1">程序无法启动，提示缺少 .NET 运行时 <a class="header-anchor" href="#程序无法启动-提示缺少-net-运行时" aria-label="Permalink to &quot;程序无法启动，提示缺少 .NET 运行时&quot;">​</a></h3><p>ICC-CE 需要 .NET 6 桌面运行时。请到微软官网搜索 &quot;.NET Desktop Runtime 6.x&quot; 下载对应架构（x64 / x86）的版本。安装版会在需要时自动提示下载。</p><h3 id="绿色版无法启动" tabindex="-1">绿色版无法启动 <a class="header-anchor" href="#绿色版无法启动" aria-label="Permalink to &quot;绿色版无法启动&quot;">​</a></h3><p>多半是缺少 .NET 6 桌面运行时，请按上述方式安装。如果确认已安装，请检查下载的压缩包是否完整，尝试重新解压。</p><h3 id="安装版提示-无法安装" tabindex="-1">安装版提示&quot;无法安装&quot; <a class="header-anchor" href="#安装版提示-无法安装" aria-label="Permalink to &quot;安装版提示&quot;无法安装&quot;&quot;">​</a></h3><p>可能是系统版本过低，请确认 Windows 10 版本 ≥ 1809（build 17763）。也可能是杀毒软件误报，请将 ICC-CE 加入白名单。</p><h3 id="运行时提示-已停止工作" tabindex="-1">运行时提示&quot;已停止工作&quot; <a class="header-anchor" href="#运行时提示-已停止工作" aria-label="Permalink to &quot;运行时提示&quot;已停止工作&quot;&quot;">​</a></h3><ol><li>检查系统版本是否满足要求</li><li>尝试以管理员身份运行</li><li>查看日志文件（<code>%AppData%\\InkCanvasForClass CE\\Logs\\</code>）了解详细错误信息</li><li>如持续崩溃，请提交 GitHub Issue 并附上日志</li></ol><h2 id="ppt-联动" tabindex="-1">PPT 联动 <a class="header-anchor" href="#ppt-联动" aria-label="Permalink to &quot;PPT 联动&quot;">​</a></h2><h3 id="进入-ppt-放映后没有自动进入标注模式" tabindex="-1">进入 PPT 放映后没有自动进入标注模式 <a class="header-anchor" href="#进入-ppt-放映后没有自动进入标注模式" aria-label="Permalink to &quot;进入 PPT 放映后没有自动进入标注模式&quot;">​</a></h3><ol><li>确认 PowerPoint 已激活，不是保护模式/只读模式</li><li>检查 ICC-CE 设置中 PPT 联动已开启（默认开启）</li><li>检查 PowerPoint 是否以管理员身份运行，而 ICC-CE 未提权，两者权限不一致会导致无法联动</li><li>尝试切换联动模式（COM / ROT / Agent）</li></ol><h3 id="标注的墨迹保存后找不到" tabindex="-1">标注的墨迹保存后找不到 <a class="header-anchor" href="#标注的墨迹保存后找不到" aria-label="Permalink to &quot;标注的墨迹保存后找不到&quot;">​</a></h3><p>默认保存位置：<code>%AppData%\\InkCanvasForClass CE\\Saves\\</code>。可在设置中自定义保存路径，或开启保存时自动重命名避免覆盖。</p><h3 id="翻页时墨迹丢失" tabindex="-1">翻页时墨迹丢失 <a class="header-anchor" href="#翻页时墨迹丢失" aria-label="Permalink to &quot;翻页时墨迹丢失&quot;">​</a></h3><p>请确认设置中&quot;新幻灯片显示画布&quot;已开启，且&quot;退出时隐藏墨迹&quot;已开启。翻回已标注页面时，墨迹应该自动恢复。</p><h3 id="与-wps-联动不工作" tabindex="-1">与 WPS 联动不工作 <a class="header-anchor" href="#与-wps-联动不工作" aria-label="Permalink to &quot;与 WPS 联动不工作&quot;">​</a></h3><p>开启设置中的&quot;WPS 支持&quot;选项，并确保 WPS 不是以管理员身份运行。</p><h2 id="墨迹与手写" tabindex="-1">墨迹与手写 <a class="header-anchor" href="#墨迹与手写" aria-label="Permalink to &quot;墨迹与手写&quot;">​</a></h2><h3 id="笔迹延迟-卡顿" tabindex="-1">笔迹延迟/卡顿 <a class="header-anchor" href="#笔迹延迟-卡顿" aria-label="Permalink to &quot;笔迹延迟/卡顿&quot;">​</a></h3><ol><li>关闭硬件加速（设置 → 画板与墨迹 → 高级笔触 → 硬件加速）</li><li>降低墨迹平滑质量（设置 → 画板与墨迹 → 高级笔触 → 墨迹平滑质量）</li><li>关闭异步墨迹平滑</li><li>检查显卡驱动是否为最新版本</li></ol><h3 id="笔迹不流畅-有锯齿" tabindex="-1">笔迹不流畅/有锯齿 <a class="header-anchor" href="#笔迹不流畅-有锯齿" aria-label="Permalink to &quot;笔迹不流畅/有锯齿&quot;">​</a></h3><ol><li>确保高级贝塞尔平滑已开启</li><li>检查笔锋模式是否设置为&quot;关闭&quot;，关闭笔锋可让笔迹更均匀</li><li>调整笔迹平滑质量为&quot;高质量&quot;</li></ol><h3 id="手势不生效" tabindex="-1">手势不生效 <a class="header-anchor" href="#手势不生效" aria-label="Permalink to &quot;手势不生效&quot;">​</a></h3><ol><li>确保设置中手势总开关已开启</li><li>检查是否在正确的模式下使用了手势（屏幕批注模式手势和白板模式手势独立配置）</li><li>检查是否启用了&quot;仅笔书写&quot;模式，此模式下手指输入会被忽略</li><li>检查是否被其他软件（如 Windows Ink 工作区）拦截</li></ol><h3 id="形状识别不准确" tabindex="-1">形状识别不准确 <a class="header-anchor" href="#形状识别不准确" aria-label="Permalink to &quot;形状识别不准确&quot;">​</a></h3><ol><li>确认&quot;启用形状识别&quot;已开启</li><li>确认具体形状（矩形/三角形/圆形）的识别开关已开启</li><li>调整直线拉直灵敏度，尝试降低灵敏度值以提高识别精度</li><li>书写时尽量一笔完成，避免断笔</li></ol><h2 id="性能与兼容" tabindex="-1">性能与兼容 <a class="header-anchor" href="#性能与兼容" aria-label="Permalink to &quot;性能与兼容&quot;">​</a></h2><h3 id="程序占用-cpu-内存过高" tabindex="-1">程序占用 CPU/内存过高 <a class="header-anchor" href="#程序占用-cpu-内存过高" aria-label="Permalink to &quot;程序占用 CPU/内存过高&quot;">​</a></h3><ol><li>关闭硬件加速</li><li>降低墨迹平滑质量</li><li>关闭异步墨迹平滑</li><li>减少日志级别（如从&quot;调试&quot;改为&quot;信息&quot;）</li><li>关闭悬浮窗拦截功能（该功能会增加性能开销）</li><li>检查是否有其他进程与 ICC-CE 冲突</li></ol><h3 id="与某些软件冲突" tabindex="-1">与某些软件冲突 <a class="header-anchor" href="#与某些软件冲突" aria-label="Permalink to &quot;与某些软件冲突&quot;">​</a></h3><p>ICC-CE 的悬浮窗拦截功能可屏蔽希沃、鸿合等教学软件的浮动窗口。如果遇到其他软件冲突，可尝试关闭该功能或调整相关设置。</p><h3 id="多显示器支持" tabindex="-1">多显示器支持 <a class="header-anchor" href="#多显示器支持" aria-label="Permalink to &quot;多显示器支持&quot;">​</a></h3><p>ICC-CE 支持多显示器环境，可在设置中启用多显示器相关选项。如果遇到画布显示异常，尝试开启&quot;多显示器画布修复&quot;。</p><h2 id="文件与数据" tabindex="-1">文件与数据 <a class="header-anchor" href="#文件与数据" aria-label="Permalink to &quot;文件与数据&quot;">​</a></h2><h3 id="如何备份配置和数据" tabindex="-1">如何备份配置和数据 <a class="header-anchor" href="#如何备份配置和数据" aria-label="Permalink to &quot;如何备份配置和数据&quot;">​</a></h3><p>备份 <code>%AppData%\\InkCanvasForClass CE\\</code> 整个目录即可。重装系统或迁移到新电脑时，将备份数据复制到相同路径。</p><h3 id="如何彻底卸载" tabindex="-1">如何彻底卸载 <a class="header-anchor" href="#如何彻底卸载" aria-label="Permalink to &quot;如何彻底卸载&quot;">​</a></h3><ul><li><strong>安装版</strong>：设置 → 应用 → 已安装的应用 → InkCanvasForClass CE → 卸载</li><li><strong>绿色版</strong>：直接删除整个文件夹</li></ul><p>卸载不会自动清除用户配置与墨迹存档，需要彻底清理时请手动删除 <code>%AppData%\\InkCanvasForClass CE\\</code> 目录。</p><h3 id="如何恢复默认设置" tabindex="-1">如何恢复默认设置 <a class="header-anchor" href="#如何恢复默认设置" aria-label="Permalink to &quot;如何恢复默认设置&quot;">​</a></h3><p>删除 <code>%AppData%\\InkCanvasForClass CE\\Configs\\Settings.json</code>，程序将在下次启动时生成默认配置。建议先备份原文件。</p><h2 id="更新相关" tabindex="-1">更新相关 <a class="header-anchor" href="#更新相关" aria-label="Permalink to &quot;更新相关&quot;">​</a></h2><h3 id="如何切换更新通道" tabindex="-1">如何切换更新通道 <a class="header-anchor" href="#如何切换更新通道" aria-label="Permalink to &quot;如何切换更新通道&quot;">​</a></h3><p>在设置中修改&quot;更新通道&quot;即可。Beta 通道更新最快，正式版最稳定。</p><h3 id="跨通道切换后出现异常" tabindex="-1">跨通道切换后出现异常 <a class="header-anchor" href="#跨通道切换后出现异常" aria-label="Permalink to &quot;跨通道切换后出现异常&quot;">​</a></h3><p>从 Beta 回退到正式版时，可能出现新版本写入的配置项无法被旧版本识别的情况。如遇异常，请备份后删除配置文件让程序重新生成。</p><h3 id="更新失败" tabindex="-1">更新失败 <a class="header-anchor" href="#更新失败" aria-label="Permalink to &quot;更新失败&quot;">​</a></h3><ol><li>检查网络连接</li><li>尝试手动下载最新版本安装包</li><li>检查更新通道设置是否正确</li><li>查看日志文件了解详细错误信息</li></ol><h2 id="如何获取帮助" tabindex="-1">如何获取帮助 <a class="header-anchor" href="#如何获取帮助" aria-label="Permalink to &quot;如何获取帮助&quot;">​</a></h2><ul><li><strong>GitHub Issues</strong>：访问项目仓库提交问题</li><li><strong>日志文件</strong>：<code>%AppData%\\InkCanvasForClass CE\\Logs\\</code>，提交问题时请附上日志</li><li><strong>配置导出</strong>：如需帮助排查问题，可导出设置分享给开发者</li></ul>',51))])}const k=r(u,[["render",c]]);export{m as __pageData,k as default};
